// Make a carnival-style application which selects a random number between 0 and 500 on the click of a button. Find 5 different images which represent 5 different levels of prizes that the person can win based on what the number is. Also, display a message which tells the person what they won.

// Solution

let strength;

let strengthMessage = d3.select("#strength-level");
let prizeImage = d3.select("#prize-image")
  .attr("width", "200px");
let prizeMessage = d3.select("#prize-message");

const prizePicker = num => {
  if (num <= 100) {
    prizeImage.attr("src", "https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Yo-Yo-Plastic-Toy-Green.jpg/1024px-Yo-Yo-Plastic-Toy-Green.jpg");
    prizeMessage.text("You won a yo-yo!")
  } else if (num <= 200) {
    prizeImage.attr("src", "https://cdn2.bigcommerce.com/server100/yt68tfv9/products/4101/images/18396/bw-speedyhorseshoe-2__61580.1502572729.500.659.jpg?c=2");
    prizeMessage.text("You won a frisbee!")
  } else if (num <= 300) {
    prizeImage.attr("src", "https://shop.wilson.com/media/catalog/product/cache/38/image/9df78eab33525d08d6e5fb8d27136e95/f/1/f1cc270c8ed3d2dd9ec7323cd969ba5f050ac2ab_WTF1100IDBRS_0_NFL_101_Game_Ball_Official.jpeg");
    prizeMessage.text("You won a football!")
  } else if (num <= 400) {
    prizeImage.attr("src", "https://shop.wilson.com/media/catalog/product/cache/38/image/9df78eab33525d08d6e5fb8d27136e95/f/f/ff53b5da37dd22488a0e219068509de52c6a8b6c_WTB0516V_Evolution_JIMMY_WALKER_Custom_Laser_Top_Detail_01_v3.jpg");
    prizeMessage.text("You won a basketball!")
  } else {
    prizeImage.attr("src", "https://www.melissaanddoug.com/dw/image/v2/BBDH_PRD/on/demandware.static/-/Sites-master-catalog/default/dw095d66be/large/002138_1.jpg?sw=562&sh=570&sm=fit");
    prizeMessage.text("You won a teddy bear!")
  }
}

d3.select("#button")
  .on("click", () => {
    strength = Math.floor(Math.random() * 500);
    strengthMessage.text("You hit " + strength);
    prizePicker(strength);
  })
